begin;
insert into auth.users(id,email,email_confirmed_at)values('30000000-0000-4000-8000-000000000001','invoice@example.invalid',now());
insert into public.user_profiles(id)values('30000000-0000-4000-8000-000000000001');
insert into public.companies(id,name)values('30000000-0000-4000-8000-000000000011','Invoice fixture');
insert into public.user_company_roles(company_id,user_id,role)values('30000000-0000-4000-8000-000000000011','30000000-0000-4000-8000-000000000001','Super Admin');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
do $$declare c uuid:='30000000-0000-4000-8000-000000000011';asset uuid;income uuid;liability uuid;bank_ledger uuid;receivable uuid;sales uuid;cgst uuid;sgst uuid;bank uuid;party uuid;invoice uuid;j uuid;payment uuid;payload jsonb;archived uuid;snapshot jsonb;note uuid;before_count integer;begin
 asset:=public.save_account(c,'{"kind":"group","name":"Assets","type":"Asset"}');income:=public.save_account(c,'{"kind":"group","name":"Income","type":"Income"}');liability:=public.save_account(c,'{"kind":"group","name":"Liabilities","type":"Liability"}');
 bank_ledger:=public.save_account(c,jsonb_build_object('kind','ledger','name','Bank','code','BANK','groupId',asset));receivable:=public.save_account(c,jsonb_build_object('kind','ledger','name','Receivable','code','AR','groupId',asset));sales:=public.save_account(c,jsonb_build_object('kind','ledger','name','Sales','code','SALES','groupId',income));cgst:=public.save_account(c,jsonb_build_object('kind','ledger','name','CGST','code','CGST','groupId',liability));sgst:=public.save_account(c,jsonb_build_object('kind','ledger','name','SGST','code','SGST','groupId',liability));
 bank:=public.save_bank_account(c,jsonb_build_object('accountId',bank_ledger,'kind','Bank','name','Fixture bank'));
 party:=public.save_party(c,'{"kind":"Customer","name":"Captured customer","email":"customer@example.invalid"}');
 payload:=jsonb_build_object('kind','Sales','partyId',party,'invoiceNumber','S-001','date','2026-09-01','dueDate','2026-09-30','taxMode','CGST_SGST','reviewReference','Illustrative reviewed fixture, not a legal default','controlAccountId',receivable,'baseAccountId',sales,'cgstAccountId',cgst,'sgstAccountId',sgst,'items',jsonb_build_array(jsonb_build_object('description','Fixture item','quantity','1','unitPriceMinor',10000,'discountMinor',0,'taxBasisPoints',1800)));
 invoice:=public.create_invoice(c,payload);
 if(select total_minor from public.invoices where id=invoice)<>11800 or(select cgst_minor from public.invoices where id=invoice)<>900 then raise exception 'FAIL exact invoice totals';end if;
 perform public.save_party(c,jsonb_build_object('kind','Customer','name','Changed customer'),party,1);
 if(select party_snapshot->>'name'from public.invoices where id=invoice)<>'Captured customer'then raise exception 'FAIL invoice party snapshot changed';end if;
 perform public.create_invoice(c,payload||jsonb_build_object('id',invoice,'expectedVersion',1,'invoiceNumber','S-001-EDIT'));
 begin perform public.create_invoice(c,payload||jsonb_build_object('id',invoice,'expectedVersion',1));raise exception 'FAIL stale draft edit';exception when serialization_failure then null;end;
 if(select count(*)from public.invoice_items where company_id=c and invoice_id=invoice)<>1 then raise exception 'FAIL draft edit duplicated items';end if;
 begin perform public.post_invoice(c,invoice,2);raise exception 'FAIL invoice posted without fiscal year';exception when check_violation then null;end;
 if exists(select 1 from public.journal_entries where company_id=c)then raise exception 'FAIL failed posting left journal';end if;
 perform public.configure_financial_year(c,'2026-04-01','2027-03-31');j:=public.post_invoice(c,invoice,2);
 if(select status from public.journal_entries where id=j)<>'Posted'then raise exception 'FAIL invoice journal not posted';end if;
 begin perform public.post_invoice(c,invoice,2);raise exception 'FAIL duplicate invoice posting';exception when serialization_failure then null;end;
 payment:=public.record_invoice_payment(c,invoice,bank,5000,'2026-09-05','FIXTURE-REF','Manually reviewed fixture receipt');
 select count(*)into before_count from public.journal_entries where company_id=c;
 begin perform public.record_invoice_payment(c,invoice,bank,5000,'2026-09-05','FIXTURE-REF','Duplicate evidence');raise exception 'FAIL duplicate bank reference';exception when unique_violation then null;end;
 if(select count(*)from public.journal_entries where company_id=c)<>before_count then raise exception 'FAIL duplicate receipt left journal';end if;
 begin perform public.record_invoice_payment(c,invoice,bank,7000,'2026-09-06','EXCESS','Excess fixture');raise exception 'FAIL overpayment accepted';exception when check_violation then null;end;
 perform public.record_invoice_payment(c,invoice,bank,6800,'2026-09-06','FIXTURE-FINAL','Manually reviewed final fixture receipt');
 if(select balance_minor from public.account_balances(c)where account_id=receivable)<>0 or(select balance_minor from public.account_balances(c)where account_id=bank_ledger)<>11800 then raise exception 'FAIL receipt ledger balances';end if;
 begin perform public.cancel_invoice(c,invoice,3,'2026-09-10','Fixture correction');raise exception 'FAIL paid invoice cancelled';exception when check_violation then null;end;
 begin perform public.reverse_journal(c,j,'2026-09-10','Bypass source');raise exception 'FAIL source journal reversed directly';exception when check_violation then null;end;
 for payment in select t.id from public.bank_transactions t where t.company_id=c loop perform public.reverse_bank_transaction(c,payment,'2026-09-10','Incorrect fixture payment evidence');end loop;
 perform public.cancel_invoice(c,invoice,3,'2026-09-10','Fixture invoice correction in books');
 if(select status from public.invoices where id=invoice)<>'Cancelled'or exists(select 1 from public.account_balances(c)where balance_minor<>0)then raise exception 'FAIL invoice correction balance/status';end if;
 begin perform public.create_invoice(c,payload||jsonb_build_object('invoiceNumber','BAD','items',jsonb_build_array(jsonb_build_object('description','Invalid discount','quantity','1','unitPriceMinor',100,'discountMinor',101))));raise exception 'FAIL invalid discount accepted';exception when check_violation then null;end;
 if exists(select 1 from public.invoices where company_id=c and invoice_number='BAD')then raise exception 'FAIL failed draft persisted';end if;

 -- Purchase-credit review uses explicit eligible amounts; configured tax is not automatically eligible.
 asset:=public.save_account(c,'{"kind":"group","name":"Expenses","type":"Expense"}');
 income:=public.save_account(c,jsonb_build_object('kind','ledger','name','Purchase expense','code','PURCHASE','groupId',asset));

 invoice:=public.create_invoice(c,payload||jsonb_build_object('invoiceNumber','NOTES-TEST'));perform public.post_invoice(c,invoice,1);
 note:=public.post_invoice_note(c,invoice,2,'{"kind":"Credit","number":"CN-01","date":"2026-09-10","taxableMinor":1000,"cgstMinor":90,"sgstMinor":90,"igstMinor":0,"reason":"Reviewed price correction","reviewReference":"Tax review fixture"}');
 if(select adjustment_minor from public.invoices where id=invoice)<>-1180 or(select status from public.invoice_notes where id=note)<>'Posted'then raise exception 'FAIL credit note totals';end if;
 begin perform public.post_invoice_note(c,invoice,2,'{}');raise exception 'FAIL stale note';exception when serialization_failure then null;end;
 begin perform public.record_invoice_payment(c,invoice,bank,11800,'2026-09-11','NOTE-EXCESS','Excess after credit');raise exception 'FAIL note payment cap';exception when check_violation then null;end;
 begin perform public.cancel_invoice(c,invoice,3,'2026-09-11','Has active note');raise exception 'FAIL cancellation with note';exception when check_violation then null;end;
 begin perform public.reverse_journal(c,(select journal_id from public.invoice_notes where id=note),'2026-09-11','Bypass');raise exception 'FAIL generic note reversal';exception when check_violation then null;end;
 perform public.reverse_invoice_note(c,note,1,'2026-09-11','Correction of credit note');
 if(select adjustment_minor from public.invoices where id=invoice)<>0 then raise exception 'FAIL note reversal restores balance';end if;
 note:=public.post_invoice_note(c,invoice,4,'{"kind":"Debit","number":"DN-01","date":"2026-09-12","taxableMinor":1000,"cgstMinor":90,"sgstMinor":90,"igstMinor":0,"reason":"Additional reviewed service","reviewReference":"Tax review fixture"}');
 perform public.record_invoice_payment(c,invoice,bank,12980,'2026-09-12','NOTES-FULL','Actual fixture evidence');
 begin perform public.reverse_invoice_note(c,note,1,'2026-09-13','Would overpay');raise exception 'FAIL debit reversal overpayment';exception when check_violation then null;end;
 for payment in select transaction_id from public.invoice_payments where company_id=c and invoice_id=invoice loop perform public.reverse_bank_transaction(c,payment,'2026-09-13','Fixture evidence correction');end loop;
 perform public.reverse_invoice_note(c,note,1,'2026-09-13','Corrected debit note');perform public.cancel_invoice(c,invoice,6,'2026-09-14','Fixture complete');
 party:=public.save_party(c,'{"kind":"Vendor","name":"Actual vendor fixture"}');
 asset:=public.save_account(c,'{"kind":"group","name":"Input Assets","type":"Asset"}');
 receivable:=public.save_account(c,jsonb_build_object('kind','ledger','name','Input CGST','code','INPUTCGST','groupId',asset));
 bank_ledger:=public.save_account(c,jsonb_build_object('kind','ledger','name','Input SGST','code','INPUTSGST','groupId',asset));
 liability:=public.save_account(c,jsonb_build_object('kind','ledger','name','Purchase payable','code','AP','groupId',liability));
 payload:=jsonb_build_object('kind','Purchase','partyId',party,'invoiceNumber','P-001','date','2026-09-01','dueDate','2026-09-30','taxMode','CGST_SGST','reviewReference','Reviewed illustrative tax fixture','controlAccountId',liability,'baseAccountId',income,'cgstAccountId',receivable,'sgstAccountId',bank_ledger,'items',jsonb_build_array(jsonb_build_object('description','Purchase fixture','quantity','1','unitPriceMinor',10000,'discountMinor',0,'taxBasisPoints',1800)));
 invoice:=public.create_invoice(c,payload);
 begin perform public.review_gst_credit(c,invoice,0,'{"cgstMinor":0,"sgstMinor":0,"igstMinor":0,"reviewReference":"Draft"}');raise exception 'FAIL draft GST credit';exception when check_violation then null;end;
 perform public.post_invoice(c,invoice,1);
 begin perform public.review_gst_credit(c,invoice,0,'{"cgstMinor":901,"sgstMinor":900,"igstMinor":0,"reviewReference":"Excess"}');raise exception 'FAIL excess credit';exception when check_violation then null;end;
 perform public.review_gst_credit(c,invoice,0,'{"cgstMinor":500,"sgstMinor":500,"igstMinor":0,"reviewReference":"Partial eligibility reviewed"}');
 begin perform public.post_invoice_note(c,invoice,2,'{"kind":"Credit","number":"PURCHASE-CREDIT-BLOCK","date":"2026-09-20","taxableMinor":10000,"cgstMinor":900,"sgstMinor":900,"igstMinor":0,"reason":"Full credit","reviewReference":"Reviewed"}');raise exception 'FAIL credit exceeds reviewed eligibility';exception when check_violation then null;end;
 begin perform public.review_gst_credit(c,invoice,0,'{"cgstMinor":0,"sgstMinor":0,"igstMinor":0,"reviewReference":"Stale"}');raise exception 'FAIL stale credit';exception when serialization_failure then null;end;
 perform public.review_gst_credit(c,invoice,1,'{"cgstMinor":0,"sgstMinor":0,"igstMinor":0,"reviewReference":"Eligibility corrected"}');
 note:=public.post_invoice_note(c,invoice,2,'{"kind":"Credit","number":"PURCHASE-CREDIT","date":"2026-09-20","taxableMinor":10000,"cgstMinor":900,"sgstMinor":900,"igstMinor":0,"reason":"Full credit","reviewReference":"Reviewed"}');
 begin perform public.review_gst_credit(c,invoice,2,'{"cgstMinor":1,"sgstMinor":0,"igstMinor":0,"reviewReference":"Above remaining tax"}');raise exception 'FAIL eligibility exceeds net note tax';exception when check_violation then null;end;
 perform public.reverse_invoice_note(c,note,1,'2026-09-21','Restore fixture invoice tax');
 if(select cgst_minor from public.gst_credit_reviews where invoice_id=invoice)<>0 or(select version from public.gst_credit_reviews where invoice_id=invoice)<>2 then raise exception 'FAIL credit correction';end if;

 archived:=public.capture_gst_book_review(c,'2026-09-01','Fixture archived books');select content into snapshot from public.gst_book_reviews where id=archived;
 if jsonb_array_length(snapshot->'rows')=0 then raise exception 'FAIL archived book events absent';end if;
 perform public.review_gst_credit(c,invoice,2,'{"cgstMinor":200,"sgstMinor":200,"igstMinor":0,"reviewReference":"Later reviewed eligibility"}');
 if(select content from public.gst_book_reviews where id=archived)is distinct from snapshot then raise exception 'FAIL archive changed with eligibility';end if;
 if(select count(*)from public.gst_credit_review_history where company_id=c and invoice_id=invoice)<>3 then raise exception 'FAIL immutable credit review history';end if;
 begin update public.gst_book_reviews set content='{}'where id=archived;raise exception 'FAIL archive modification';exception when insufficient_privilege then null;end;
 begin perform public.capture_gst_book_review(c,'2026-09-01','Fixture archived books');raise exception 'FAIL duplicate archive reference';exception when unique_violation then null;end;
 begin perform public.capture_gst_book_review('30000000-0000-4000-8000-000000000099','2026-09-01','Other tenant');raise exception 'FAIL cross-tenant archive';exception when insufficient_privilege then null;end;
 begin perform public.save_party('30000000-0000-4000-8000-000000000099','{"kind":"Customer","name":"Forbidden"}');raise exception 'FAIL cross-company party write';exception when insufficient_privilege then null;end;
end $$;
rollback;
